<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';require_once __DIR__.'/includes/individual_lesson_context.php';
if(!isset($_SESSION['trener_id'])){header('Location: login.php');exit;}staffRequireActivePosition('program_coordinator');
function bsah(mixed$value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$context=individualLessonContextCondition($pdo,'l',INDIVIDUAL_LESSON_CONTEXT_LESSON);$today=(new DateTimeImmutable('today'))->format('Y-m-d');
$statement=$pdo->prepare("SELECT l.id,l.nazev,l.datum,l.cas_od,l.cas_do,l.slot_delka_min,l.cena_kc,l.max_osob,l.typ,l.stav,s.nazev AS venue_name,t.jmeno AS trainer_name,COUNT(r.id) AS reservations,SUM(CASE WHEN r.stav='potvrzena' THEN 1 ELSE 0 END) AS confirmed,SUM(CASE WHEN r.stav='cekaci_listina' THEN 1 ELSE 0 END) AS waiting FROM individualni_lekce l JOIN sportovist s ON s.id=l.sportoviste_id JOIN treneri t ON t.id=l.trener_id LEFT JOIN verejne_rezervace r ON r.lekce_id=l.id WHERE ".$context." AND l.datum>=? GROUP BY l.id ORDER BY l.datum,l.cas_od,l.id LIMIT 300");$statement->execute([$today]);$windows=$statement->fetchAll(PDO::FETCH_ASSOC);
?>
