<section class="card border-0 shadow-sm"><div class="card-header bg-white d-flex justify-content-between"><strong>Budoucí rezervační okna</strong><span class="text-muted"><?=count($windows)?> záznamů</span></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Služba</th><th>Termín a okno</th><th>Cena / kapacita</th><th>Rezervace</th><th>Správce</th></tr></thead><tbody><?php foreach($windows as$window):?><tr><td><strong><?=bsah($window['nazev'])?></strong><div class="small text-muted"><?=bsah($window['venue_name'])?> · <?=bsah($window['typ']==='zelena'?'přímá rezervace':'vyžaduje potvrzení')?></div></td><td><?=bsah($window['datum'])?><div class="small"><?=bsah(substr((string)$window['cas_od'],0,5).'–'.substr((string)$window['cas_do'],0,5).' · '.$window['slot_delka_min'].' min')?></div></td><td><?=number_format((float)$window['cena_kc'],0,',',' ')?> Kč<div class="small text-muted">max. <?=(int)$window['max_osob']?> osob / slot</div></td><td><strong><?=(int)$window['confirmed']?></strong> potvrzeno<div class="small text-muted"><?=(int)$window['waiting']?> čeká na listině</div></td><td><?=bsah($window['trainer_name'])?><div><a class="small" href="individualni_lekce_form.php?edit_id=<?=(int)$window['id']?>">Upravit</a></div></td></tr><?php endforeach;?><?php if($windows===[]):?><tr><td colspan="5" class="text-center text-muted py-4">Nejsou vypsaná žádná budoucí okna.</td></tr><?php endif;?></tbody></table></div></section>
